  if((config.toolsets||[]).some(name=>!['terminal','file','skills','memory'].includes(name)))throw new Error('Unsupported staging toolset.');
  if(config?.model?.provider!=='openrouter' || config.fallback_model || (config.fallback_providers?.length||0)) throw new Error('Unsupported staging model provider or fallback. Use a separately authorized staging OpenRouter grant.');
  for(const settings of Object.values(config.auxiliary||{})) if(settings?.override||settings?.base_url||settings?.api_base||settings?.api_key||settings?.key_env||settings?.api_key_env||settings?.api_mode||settings?.provider && !['auto','openrouter'].includes(settings.provider)) throw new Error('Unsupported staging auxiliary provider.');
